/**
 * Cart 场景落地页模板（/solutions/<slug>/）
 *
 * 由 `gatsby-node.js` 的 `createPages` 从 `src/data/solutions.js` 生成 —— 一个场景一页。
 * 为什么走「数据 + 模板」而不是在 `src/pages/solutions/` 下写 4 个文件：
 * 4 页结构完全相同、差异全在数据；写成手写文件后改一次版式要改 4 处（必然漂移）。
 *
 * 🔴 **写作红线**（真源 `shopifyApp/whaleal-cart/app-store-listing-draft.md`）：
 *    ① 不得把 AI 写成「生成正文 / 整封邮件 / 自动生效 / 从结账数据个性化」——
 *       AI 只出 subject / heading / intro，且须商家手动选用；
 *    ② SMS 通道只承诺**弃单单条**，不得写成营销群发；
 *    ③ 不得出现任何未核实数字（客户数 / 送达率 / 提升百分比 / 评价）；
 *    ④ 不出现第三方实现品牌名。
 *    另：提到 Messaging 时守 `BSP角色与免责边界-对外文案稿.md` §6 三条禁令。
 *
 * 🔴 `softwareApp={true}`（默认）：本族讲的是 **Whaleal Cart 这个 Shopify 应用**
 *    的挽回能力，输出 SoftwareApplication 结构化数据是**正确的**。
 *    （对照：`templates/integration.js` 与 `pages/guides/` 讲的是 Messaging 平台，
 *      那两处必须 `softwareApp={false}`。）
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../components/Layout';
import SEO from '../components/SEO';
import { SOLUTIONS } from '../data/solutions';
import { GUIDES } from '../data/guides';
import { PRODUCT_NAME, SHOPIFY_INSTALL_PAGE_PATH } from '../constants/brand';
import '../styles/marketing.css';

export default function SolutionTemplate({ pageContext }) {
  const { solution } = pageContext;
  const { name, h1, eyebrow, metaTitle, metaDescription, lede, sections, faq, guides } = solution;

  // 相关 guide 从同一份 GUIDES 数据取标题，避免在数据里重复维护一遍标题（会漂移）
  const relatedGuides = (guides || [])
    .map((slug) => GUIDES.find((g) => g.slug === slug))
    .filter(Boolean);

  // 同族其余页 —— 内链是这类落地页能否被爬到的关键，别省
  const siblings = SOLUTIONS.filter((s) => s.slug !== solution.slug);

  return (
    <Layout>
      <SEO
        title={metaTitle}
        description={metaDescription}
        pathname={`/solutions/${solution.slug}/`}
        faqs={faq}
        breadcrumbs={[
          { name: 'Home', path: '/' },
          { name: 'Solutions', path: '/solutions/' },
          { name, path: `/solutions/${solution.slug}/` },
        ]}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow">{eyebrow}</span>
          <h1>{h1}</h1>
          <p className="mk-lead">{lede}</p>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-primary" to={SHOPIFY_INSTALL_PAGE_PATH}>
              Install {PRODUCT_NAME} free
            </Link>
            <Link className="mk-btn mk-btn-secondary" to="/solutions/">
              All solutions
            </Link>
          </div>
        </header>

        {sections.map((section) => (
          <section className="mk-section" key={section.h}>
            <h2>{section.h}</h2>
            {(section.p || []).map((para, i) => (
              <p className="mk-section-lead" key={i}>
                {para}
              </p>
            ))}
            {section.bullets && (
              <ul className="mk-list">
                {section.bullets.map((b) => (
                  <li key={b}>{b}</li>
                ))}
              </ul>
            )}
          </section>
        ))}

        {faq && faq.length > 0 && (
          <section className="mk-section">
            <h2>Questions this usually raises</h2>
            <dl className="mk-faq">
              {faq.map((item) => (
                <div className="mk-faq-item" key={item.q}>
                  <dt>{item.q}</dt>
                  <dd>{item.a}</dd>
                </div>
              ))}
            </dl>
          </section>
        )}

        {(relatedGuides.length > 0 || siblings.length > 0) && (
          <section className="mk-section">
            <h2>Keep reading</h2>
            <div className="mk-grid">
              {relatedGuides.map((g) => (
                <article className="mk-card" key={g.slug}>
                  <span className="mk-card-tag">{g.readMinutes} min</span>
                  <h3>{g.title}</h3>
                  <p>{g.excerpt}</p>
                  <Link className="mk-card-link" to={`/guides/${g.slug}/`}>
                    Read the guide &rarr;
                  </Link>
                </article>
              ))}
              {siblings.map((s) => (
                <article className="mk-card" key={s.slug}>
                  <span className="mk-card-tag">Solution</span>
                  <h3>{s.name}</h3>
                  <p>{s.lede}</p>
                  <Link className="mk-card-link" to={`/solutions/${s.slug}/`}>
                    Open &rarr;
                  </Link>
                </article>
              ))}
            </div>
          </section>
        )}

        <div className="mk-scope">
          <strong>Scope.</strong> This page describes {PRODUCT_NAME} for Shopify — abandoned
          checkout detection, the timed recovery sequence, and the optional single-text channel on
          your own SMS account. Local messaging consent and opt-out rules remain the merchant&rsquo;s
          responsibility; the platform does not file or guarantee them.
        </div>
      </div>
    </Layout>
  );
}
